# O AgentCore Runtime hospeda um agent de QUALQUER framework.
# Exemplo minimo com o Strands Agents SDK (open-source da AWS):
from strands import Agent
from bedrock_agentcore.runtime import BedrockAgentCoreApp

app = BedrockAgentCoreApp()
agent = Agent(model="anthropic.claude-3-5-sonnet-20240620-v1:0")

@app.entrypoint
def handler(payload):
    # payload["prompt"] chega da invocacao. O Runtime cuida de
    # compute, sessao isolada, memory e observability para voce.
    return agent(payload["prompt"])

if __name__ == "__main__":
    app.run()   # empacota e roda o agent no AgentCore Runtime
